function writeAllOutputs(opts, detector, modes, trajectories, frames, ...
        photonEvents, photophysics, localizationTable, surfaceModel, ...
        trackTable, diffusion)
    import membrane_tracking.fluctuating_miet.*

    writetable(localizationTable, fullfile(opts.outputDir, ...
        'fluctuating_miet_localizations.csv'));
    writetable(trackTable, fullfile(opts.outputDir, ...
        'fluctuating_miet_tracks.csv'));
    writetable(diffusion.msdTable, fullfile(opts.outputDir, ...
        'fluctuating_miet_msd.csv'));
    if isfield(surfaceModel,'topography') && surfaceModel.topography.isValid
        writetable(topographyToTable(surfaceModel.topography), ...
            fullfile(opts.outputDir,'fluctuating_miet_topography.csv'));
        topographyRmse = surfaceModel.topography.rmseUm;
    else
        topographyRmse = NaN;
    end
    summary = table(opts.curvaturePerUm, surfaceModel.naive.curvaturePerUm, ...
        surfaceModel.moment.curvaturePerUm, surfaceModel.curvaturePerUm, ...
        surfaceModel.curvatureSigmaPerUm, opts.tipHeightUm, ...
        surfaceModel.tipHeightUm, surfaceModel.fieldRmsUm, ...
        surfaceModel.fieldCorrelationLengthUm, opts.diffusionUm2PerS, ...
        diffusion.DMsdCorrectedUm2PerS, diffusion.DFisherMLEUm2PerS, ...
        topographyRmse, ...
        diffusion.truthValidation.lateralLocalizationRmseUm, ...
        diffusion.meanGateAcceptanceProbability, ...
        diffusion.truthValidation.fullSurfaceLag1DiffusionUm2PerS, ...
        'VariableNames', {'trueCurvaturePerUm','naiveCurvaturePerUm', ...
        'momentCurvaturePerUm','reportedCurvaturePerUm', ...
        'curvatureSigmaPerUm','trueTipHeightUm','reportedTipHeightUm', ...
        'fittedFieldRmsUm','fittedFieldLengthUm','trueDiffusionUm2PerS', ...
        'msdDiffusionUm2PerS','mleDiffusionUm2PerS', ...
        'topographyRmseUm','lateralLocalizationRmseUm', ...
        'meanGateAcceptance','sampledTruthDiffusionUm2PerS'});
    writetable(summary, fullfile(opts.outputDir, ...
        'fluctuating_miet_summary.csv'));
    save(fullfile(opts.outputDir, 'fluctuating_miet_simulation.mat'), ...
        'opts','detector','modes','trajectories','frames','photonEvents', ...
        'photophysics','localizationTable','surfaceModel','trackTable', ...
        'diffusion','-v7.3');
end
